CREATE TABLE IF NOT EXISTS legacy_topics (id VARCHAR(64) PRIMARY KEY,name VARCHAR(100) NOT NULL) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS legacy_documents (id CHAR(32) PRIMARY KEY,topic VARCHAR(64) NOT NULL,filename VARCHAR(180) NOT NULL,sha256 CHAR(64) NOT NULL,file_blob LONGBLOB NOT NULL,page_count INT NOT NULL,ocr_pages INT NOT NULL,chunk_count INT NOT NULL,chunks JSON NOT NULL,UNIQUE KEY legacy_digest(topic,sha256),FOREIGN KEY(topic) REFERENCES legacy_topics(id) ON DELETE CASCADE) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS app_settings (name VARCHAR(80) PRIMARY KEY,value TEXT NULL) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS users (id CHAR(32) PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,name VARCHAR(80) NOT NULL,password_hash VARCHAR(255) NOT NULL,legacy_workspace BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS avatars (user_id CHAR(32) NOT NULL,slot VARCHAR(72) NOT NULL,preset VARCHAR(32) NOT NULL DEFAULT 'default',file_blob MEDIUMBLOB NULL,sha256 CHAR(64) NULL,PRIMARY KEY(user_id,slot),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS sessions (token_hash CHAR(64) PRIMARY KEY,user_id CHAR(32) NOT NULL,expires_at DATETIME(3) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX session_expiry(expires_at)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS login_attempts (id BIGINT AUTO_INCREMENT PRIMARY KEY,identity_hash CHAR(64) NOT NULL,attempted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX attempt_identity(identity_hash,attempted_at)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS topics (user_id CHAR(32) NOT NULL,id VARCHAR(64) NOT NULL,name VARCHAR(100) NOT NULL,bot_name VARCHAR(80) NOT NULL DEFAULT 'BIGRAG',theme VARCHAR(32) NOT NULL DEFAULT 'mint',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS documents (id CHAR(32) PRIMARY KEY,user_id CHAR(32) NOT NULL,topic VARCHAR(64) NOT NULL,filename VARCHAR(180) NOT NULL,sha256 CHAR(64) NOT NULL,file_blob LONGBLOB NOT NULL,page_count INT NOT NULL DEFAULT 0,ocr_pages INT NOT NULL DEFAULT 0,chunk_count INT NOT NULL DEFAULT 0,chunks JSON NULL,prepared JSON NULL,index_mode VARCHAR(20) NOT NULL DEFAULT 'original',status VARCHAR(20) NOT NULL DEFAULT 'pending',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY document_digest(user_id,topic,sha256),FOREIGN KEY(user_id,topic) REFERENCES topics(user_id,id) ON DELETE CASCADE) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS conversations (id CHAR(32) PRIMARY KEY,user_id CHAR(32) NOT NULL,topic VARCHAR(64) NOT NULL,title VARCHAR(120) NOT NULL,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(user_id,topic) REFERENCES topics(user_id,id) ON DELETE CASCADE,INDEX chat_owner(user_id,updated_at)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS messages (id BIGINT AUTO_INCREMENT PRIMARY KEY,conversation_id CHAR(32) NOT NULL,role VARCHAR(12) NOT NULL,content MEDIUMTEXT NOT NULL,metadata JSON NOT NULL,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,INDEX chat_messages(conversation_id,id)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS previews (id CHAR(32) PRIMARY KEY,user_id CHAR(32) NOT NULL,topic VARCHAR(64) NOT NULL,filename VARCHAR(180) NOT NULL,file_blob LONGBLOB NOT NULL,rag_token VARCHAR(64) NOT NULL,prepared JSON NOT NULL,expires_at DATETIME NOT NULL,FOREIGN KEY(user_id,topic) REFERENCES topics(user_id,id) ON DELETE CASCADE) ENGINE=InnoDB;
